using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using HtmlAgilityPack;

public class AirlineComparison
{
    public static async Task Main(string[] args)
    {
        var deltaData = await GetAirlineData("Delta");
        var unitedData = await GetAirlineData("United");

        Console.WriteLine("Airline Comparison");
        Console.WriteLine("------------------");

        Console.WriteLine("Delta Airlines:");
        Console.WriteLine($"Incidents: {deltaData.Incidents}");
        Console.WriteLine($"Accidents: {deltaData.Accidents}");
        Console.WriteLine($"Fatalities: {deltaData.Fatalities}");

        Console.WriteLine("\nUnited Airlines:");
        Console.WriteLine($"Incidents: {unitedData.Incidents}");
        Console.WriteLine($"Accidents: {unitedData.Accidents}");
        Console.WriteLine($"Fatalities: {unitedData.Fatalities}");
    }

    private static async Task<AirlineData> GetAirlineData(string airlineName)
    {
        string url = $"https://example.com/{airlineName}/safety-data"; // Replace with actual URL

        using (var httpClient = new HttpClient())
        {
            var htmlContent = await httpClient.GetStringAsync(url);
            var htmlDoc = new HtmlDocument();
            htmlDoc.LoadHtml(htmlContent);

            var incidentsNode = htmlDoc.DocumentNode.SelectSingleNode("//div[@id='incidents']");
            var accidentsNode = htmlDoc.DocumentNode.SelectSingleNode("//div[@id='accidents']");
            var fatalitiesNode = htmlDoc.DocumentNode.SelectSingleNode("//div[@id='fatalities']");

            int incidents = 0;
            int accidents = 0;
            int fatalities = 0;

            if (incidentsNode != null)
            {
                incidents = int.Parse(incidentsNode.InnerText.Replace(" ", "").Replace(",", ""));
            }

            if (accidentsNode != null)
            {
                accidents = int.Parse(accidentsNode.InnerText.Replace(" ", "").Replace(",", ""));
            }

            if (fatalitiesNode != null)
            {
                fatalities = int.Parse(fatalitiesNode.InnerText.Replace(" ", "").Replace(",", ""));
            }

            return new AirlineData
            {
                Incidents = incidents,
                Accidents = accidents,
                Fatalities = fatalities
            };
        }
    }
}

public class AirlineData
{
    public int Incidents { get; set; }
    public int Accidents { get; set; }
    public int Fatalities { get; set; }
}
```

### Explanation:
1. **HttpClient**: Used to make HTTP requests to the airline's safety data page.
2. **HtmlAgilityPack**: Used to parse the HTML content and extract the required data.
3. **AirlineData Class**: A simple class to store the extracted data for each airline.
4. **GetAirlineData Method**: Fetches the data from the specified URL and parses it to get the number of incidents, accidents, and fatalities.
