using System;
using System.Collections.Generic;
using System.Linq;
using Tweetinvi;

public class NameTwitterSearcher
{
    private static string apiKey = "YOUR_TWITTER_API_KEY";
    private static string apiSecretKey = "YOUR_TWITTER_API_SECRET_KEY";

    public static void Main(string[] args)
    {
        // Initialize the Twitter API
        Auth.SetUserCredentials(apiKey, apiSecretKey);

        string text = "John Doe is a famous actor and so is Lady Gaga.";
        List<string> namesToSearch = ExtractNames(text);

        foreach (var name in namesToSearch)
        {
            if (!string.IsNullOrWhiteSpace(name))
            {
                var twitterAccount = FindTwitterAccount(name);
                Console.WriteLine($"Name: {name} - Twitter Account: {twitterAccount}");
            }
        }
    }

    private static List<string> ExtractNames(string text)
    {
        // Simple regex to extract potential names
        return Regex.Matches(text, @"\b[A-Z][a-z]+(?: [A-Z][a-z]+)+\b")
                    .Cast<Match>()
                    .Select(m => m.Value)
                    .ToList();
    }

    private static string FindTwitterAccount(string name)
    {
        try
        {
            var user = User.GetByName(name);
            return user != null ? user.ScreenName : null;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error searching for {name}: {ex.Message}");
            return null;
        }
    }
